## The test

```php
use App\Jobs\SendShippingNotification;
use App\Models\Order;
use Illuminate\Support\Facades\Queue;

it('dispatches a shipping notification job when an order ships', function () {
    Queue::fake();

    $order = Order::factory()->create();

    $order->ship(); // or $this->postJson("/orders/{$order->id}/ship") for an HTTP feature test

    Queue::assertPushed(SendShippingNotification::class, function ($job) use ($order) {
        return $job->order->is($order);
    });
});
```

